"use client";

import "./button-group.css";
import type React from "react";
import { cn } from "@/lib/cn";

import { Button, type ButtonProps } from "../button";
import { ButtonGroupContext, useButtonGroupContext } from "./button-group.context";
import { buttonGroupVariants, type ButtonGroupVariants } from "./button-group.variants";

export type ButtonGroupProps = {
  size?: "sm" | "md" | "lg";
  variant?: "primary" | "secondary" | "destructive" | "outline" | "ghost";
} & ButtonGroupVariants & React.ComponentProps<"div">;

export const ButtonGroupRoot = ({
  children,
  className,
  orientation = "horizontal",
  size,
  variant,
  ...props
}: ButtonGroupProps) => {
  const slots = buttonGroupVariants({ orientation });

  return (
    <ButtonGroupContext.Provider value={{ slots, size, variant }}>
      <div
        role="group"
        className={cn(slots.root(), className)}
        {...props}
      >
        {children}
      </div>
    </ButtonGroupContext.Provider>
  );
};

export const ButtonGroupItem = ({ size, variant, ...props }: ButtonProps) => {
  const context = useButtonGroupContext();
  return (
    <Button
      size={size ?? context.size}
      variant={variant ?? context.variant}
      {...props}
    />
  );
};

export const ButtonGroup = ButtonGroupRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const buttonGroupVariants = tv({
  slots: {
    root: "button-group",
  },
  variants: {
    orientation: {
      horizontal: {
        root: "button-group--horizontal",
      },
      vertical: {
        root: "button-group--vertical",
      },
    },
  },
  defaultVariants: {
    orientation: "horizontal",
  },
});

export type ButtonGroupVariants = VariantProps<typeof buttonGroupVariants>;

"use client";

import { createContext, useContext } from "react";

import { buttonGroupVariants } from "./button-group.variants";

export type ButtonGroupContext = {
  slots: ReturnType<typeof buttonGroupVariants>;
  size?: "sm" | "md" | "lg";
  variant?: "primary" | "secondary" | "destructive" | "outline" | "ghost";
};

export const ButtonGroupContext = createContext<ButtonGroupContext | null>(null);

export const useButtonGroupContext = () => {
  const context = useContext(ButtonGroupContext);
  return context ?? { slots: buttonGroupVariants() };
};

.button-group {
  @apply inline-flex items-center select-none;
}

.button-group--horizontal {
  @apply flex-row;
}

.button-group--horizontal > button,
.button-group--horizontal > .button {
  @apply focus-visible:z-10 -ml-px rounded-none first:ml-0 first:rounded-l-md last:rounded-r-md;
}

.button-group--vertical {
  @apply flex-col items-stretch;
}

.button-group--vertical > button,
.button-group--vertical > .button {
  @apply focus-visible:z-10 -mt-px rounded-none first:mt-0 first:rounded-t-md last:rounded-b-md;
}

import {
  ButtonGroup,
  ButtonGroupItem,
  ButtonGroupRoot,
} from "./button-group";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/button-group/content.md
 */
export const ButtonGroupContainer = {
  Item: ButtonGroupItem,
  Root: ButtonGroupRoot,
};

export {
  ButtonGroup,
  ButtonGroupItem,
  ButtonGroupRoot,
};

export type {
  ButtonGroupProps,
} from "./button-group";
export { ButtonGroupContext, useButtonGroupContext } from "./button-group.context";
export { type ButtonGroupVariants, buttonGroupVariants } from "./button-group.variants";
